NEW_FILES = {'minicut/workspace/fx_graph_model.py': '"""FX graph document (Patch 52) - everything the FX node editor does to a graph, with no Qt in it.\n\nThe editor window only draws this document and forwards the user\'s actions to it, so the rules (what can be linked,\nundo / redo, copy / paste, search) can be tested without a screen.\n\nA graph is  {"nodes": [{"id", "type", "x", "y", "p": {param: value}, "ex": {param: label}, "mute": bool}],\n             "links": [{"from": node id, "fo": output slot, "to": node id, "ti": input socket}]}\n"ti" is a position in custom.in_sockets(type): first the picture / value inputs, then one socket for every number or\ncolour parameter. "ex" lists the parameters that are exposed as a slider of the effect (in the inspector).\n"""\nimport copy, json, re, time, uuid\n\nfrom ..render.fxpack.custom import (FX_NODE_TYPES, in_sockets, out_kind, collect_param_specs, compile_effect)\n\nCLIP_KIND = "minicut-fx-nodes"\nCAT_ORDER = ["Image", "Source", "Color", "Blur", "Distort", "Composite", "Utility", "Parameter"]\n\n# extra words for the node search (English + Thai), on top of the node\'s title and category\nFX_KEYWORDS = {\n    "fx_input": "picture source clip original input รูป ต้นฉบับ อินพุต",\n    "fx_output": "result final output export ผลลัพธ์ เอาต์พุต",\n    "fx_brightness": "light dark contrast exposure สว่าง มืด คอนทราสต์ ความสว่าง",\n    "fx_hue_sat": "color colour hue saturation vivid สี ความอิ่ม โทนสี",\n    "fx_tint_node": "color colour wash overlay ย้อมสี โทนสี",\n    "fx_invert_node": "negative reverse กลับสี ฟิล์มลบ",\n    "fx_bw_node": "grey gray black white monochrome desaturate ขาวดำ",\n    "fx_threshold": "binary black white cutoff ขาวดำ ตัด",\n    "fx_blur_node": "soft glow smooth gaussian เบลอ นุ่ม ฟุ้ง",\n    "fx_box_blur": "soft fast เบลอ นุ่ม",\n    "fx_displace": "distort warp map bend บิด ดิสเพลซ",\n    "fx_wave_warp": "ripple wobble water distort คลื่น บิด น้ำ",\n    "fx_chromatic_ab": "rgb split glitch lens fringe แยกสี กลิตช์",\n    "fx_pixelate_node": "mosaic blocks retro 8bit โมเสก พิกเซล",\n    "fx_over": "layer composite stack put on top ซ้อน เลเยอร์",\n    "fx_blend_mode": "multiply screen overlay add difference mix layer ผสม ซ้อน",\n    "fx_mask_alpha": "cut transparent matte stencil alpha มาสก์ โปร่งใส ตัด",\n    "fx_mix": "blend crossfade fade lerp ผสม เฟด",\n    "fx_noise_tex": "texture grain clouds random fbm สุ่ม เม็ด เมฆ",\n    "fx_solid": "colour color flat fill background สีพื้น ทึบ พื้นหลัง",\n    "fx_gradient": "ramp fade colour color ไล่สี เกรเดียนต์",\n    "fx_checker": "chess squares pattern transparent grid ตาหมากรุก ลาย",\n    "fx_time": "seconds clock progress animate เวลา แอนิเมชัน",\n    "fx_lfo": "oscillator sine wave pulse animate loop repeat คลื่น วนซ้ำ แอนิเมชัน",\n    "fx_map_range": "remap scale range convert ปรับช่วง แปลงค่า",\n    "fx_math": "add subtract multiply divide calculate บวก ลบ คูณ หาร คำนวณ",\n    "fx_constant": "number value fixed ตัวเลข ค่าคงที่",\n    "fx_param_float": "slider inspector control number พารามิเตอร์ สไลเดอร์",\n    "fx_param_int": "slider inspector control whole number พารามิเตอร์ จำนวนเต็ม",\n    "fx_param_color": "colour color picker inspector พารามิเตอร์ ตัวเลือกสี",\n}\n\n\ndef new_id() -> str:\n    return uuid.uuid4().hex[:8]\n\n\ndef default_graph() -> dict:\n    """A new effect starts with the picture already wired to the result (so it works at once)."""\n    return {"nodes": [{"id": "in0", "type": "fx_input", "x": 60, "y": 120, "p": {}},\n                      {"id": "out0", "type": "fx_output", "x": 520, "y": 120, "p": {}}],\n            "links": [{"from": "in0", "fo": 0, "to": "out0", "ti": 0}]}\n\n\ndef node_defaults(typ: str) -> dict:\n    return {ps[0]: ps[3] for ps in FX_NODE_TYPES.get(typ, {}).get("params", [])}\n\n\ndef node_rows(typ: str) -> list:\n    """What a node shows, row by row (the window draws exactly this). Outputs come first, then one row for every\n    input socket (a number / colour parameter row also holds its value field), then the parameters that have no socket.\n    Row: {"out": slot or None, "in": socket or None, "kind": \'image\'|\'float\'|\'color\'|param kind|None, "label", "param"}"""\n    spec = FX_NODE_TYPES.get(typ)\n    if not spec: return []\n    rows = [{"out": j, "in": None, "kind": out_kind(typ), "label": lab, "param": None} for j, lab in enumerate(spec.get("outs", []))]\n    used = set()\n    for i, (lab, kind, pk) in enumerate(in_sockets(typ)):\n        rows.append({"out": None, "in": i, "kind": kind, "label": lab, "param": pk})\n        if pk: used.add(pk)\n    for ps in spec.get("params", []):\n        if ps[0] in used: continue\n        rows.append({"out": None, "in": None, "kind": ps[2], "label": ps[1], "param": ps[0]})\n    return rows\n\n\ndef param_spec(typ: str, key: str):\n    return next((ps for ps in FX_NODE_TYPES.get(typ, {}).get("params", []) if ps[0] == key), None)\n\n\ndef can_expose(typ: str, key: str) -> bool:\n    ps = param_spec(typ, key)\n    return bool(ps) and ps[2] != "text" and typ not in ("fx_param_float", "fx_param_int", "fx_param_color")\n\n\ndef link_problem(graph: dict, a: str, fo: int, b: str, ti: int):\n    """None when a -> b can be linked, otherwise the reason (short, shown to the person)."""\n    nodes = {n["id"]: n for n in graph.get("nodes", [])}\n    if a not in nodes or b not in nodes: return "missing node"\n    if a == b: return "A node cannot be linked to itself"\n    ta, tb = nodes[a]["type"], nodes[b]["type"]\n    if not (0 <= fo < max(1, len(FX_NODE_TYPES[ta].get("outs", [])))) or not FX_NODE_TYPES[ta].get("outs"): return "That socket is not an output"\n    socks = in_sockets(tb)\n    if not (0 <= ti < len(socks)): return "That socket is not an input"\n    want, got = socks[ti][1], out_kind(ta)\n    if got != want: return "These sockets do not fit (%s -> %s)" % (got, want)\n    if _reaches(graph, b, a): return "That link would make a loop"\n    return None\n\n\ndef _reaches(graph: dict, start: str, goal: str) -> bool:\n    """True when `goal` can be reached from `start` by following links forward."""\n    nxt = {}\n    for lk in graph.get("links", []): nxt.setdefault(lk["from"], []).append(lk["to"])\n    seen, stack = set(), [start]\n    while stack:\n        n = stack.pop()\n        if n == goal: return True\n        if n in seen: continue\n        seen.add(n); stack.extend(nxt.get(n, []))\n    return False\n\n\ndef normalize(graph) -> dict:\n    """A clean copy of a graph read from a file: unknown nodes and broken links are dropped, defaults are filled in."""\n    out = {"nodes": [], "links": []}\n    if not isinstance(graph, dict): return default_graph()\n    ids = set()\n    for n in graph.get("nodes", []) if isinstance(graph.get("nodes"), list) else []:\n        if not isinstance(n, dict) or n.get("type") not in FX_NODE_TYPES: continue\n        nid = str(n.get("id") or new_id())\n        if nid in ids: nid = new_id()\n        ids.add(nid)\n        d = {"id": nid, "type": n["type"], "x": _num(n.get("x"), 0.0), "y": _num(n.get("y"), 0.0),\n             "p": dict(n["p"]) if isinstance(n.get("p"), dict) else {}}\n        if n.get("mute"): d["mute"] = True\n        if isinstance(n.get("ex"), dict) and n["ex"]: d["ex"] = {str(k): str(v) for k, v in n["ex"].items() if param_spec(d["type"], str(k))}\n        out["nodes"].append(d)\n    # a node id that was changed above can no longer be found by the links: links are matched on the original ids only\n    kept = {n["id"] for n in out["nodes"]}\n    for lk in graph.get("links", []) if isinstance(graph.get("links"), list) else []:\n        try: a, fo, b, ti = str(lk["from"]), int(lk.get("fo", 0)), str(lk["to"]), int(lk.get("ti", 0))\n        except Exception: continue\n        if a not in kept or b not in kept: continue\n        if link_problem(out, a, fo, b, ti) is None:\n            out["links"] = [l for l in out["links"] if not (l["to"] == b and l["ti"] == ti)]\n            out["links"].append({"from": a, "fo": fo, "to": b, "ti": ti})\n    return out\n\n\ndef _num(v, d):\n    try:\n        v = float(v)\n        return v if v == v and abs(v) < 1e7 else d\n    except Exception: return d\n\n\n# ── search ────────────────────────────────────────────────────────────────────\n\ndef search_nodes(query: str, limit: int = 40) -> list:\n    """Node types that match `query`, best first. Empty query = every node, in palette order."""\n    q = (query or "").strip().lower()\n    items = []\n    for typ, spec in FX_NODE_TYPES.items():\n        title = spec.get("title", typ); cat = spec.get("cat", "")\n        if not q:\n            items.append((_cat_rank(cat), title.lower(), typ)); continue\n        s = _score(q, title.lower(), cat.lower(), FX_KEYWORDS.get(typ, "").lower(), typ.lower())\n        if s > 0: items.append((-s, title.lower(), typ))\n    items.sort()\n    return [t for _s, _t, t in items][:limit]\n\n\ndef _cat_rank(cat): return CAT_ORDER.index(cat) if cat in CAT_ORDER else len(CAT_ORDER)\n\n\ndef _score(q, title, cat, kw, typ) -> int:\n    toks = [t for t in re.split(r"\\s+", q) if t]\n    total = 0\n    for t in toks:\n        best = 0\n        if title == t: best = 100\n        elif title.startswith(t): best = 80\n        elif any(w.startswith(t) for w in re.split(r"[\\s()/\\-]+", title)): best = 65\n        elif t in title: best = 50\n        elif any(w.startswith(t) for w in kw.split()): best = 45\n        elif t in kw: best = 35\n        elif t in cat: best = 25\n        elif t in typ: best = 20\n        elif _subseq(t, title): best = 10\n        if best == 0: return 0\n        total += best\n    return total\n\n\ndef _subseq(t, s):\n    it = iter(s)\n    return all(c in it for c in t)\n\n\n# ── the document ──────────────────────────────────────────────────────────────\n\nclass FxDoc:\n    """A graph with undo / redo. Every change goes through a method of this class."""\n    UNDO_LIMIT = 100\n    COALESCE_SECONDS = 1.2        # dragging a number field makes one undo step, not hundreds\n\n    def __init__(self, graph=None):\n        self.graph = normalize(graph) if graph is not None else default_graph()\n        self._undo, self._redo = [], []\n        self._last_key, self._last_t = None, 0.0\n        self.version = 0\n        self._saved = self._dump()\n        self.on_change = None           # called after every change (the window refreshes itself)\n\n    # -- bookkeeping --\n    def _dump(self): return json.dumps(self.graph, sort_keys=True)\n    def is_dirty(self) -> bool: return self._dump() != self._saved\n    def mark_saved(self): self._saved = self._dump()\n    def can_undo(self) -> bool: return bool(self._undo)\n    def can_redo(self) -> bool: return bool(self._redo)\n\n    def _push(self, key=None):\n        now = time.monotonic()\n        if key is not None and key == self._last_key and now - self._last_t < self.COALESCE_SECONDS:\n            self._last_t = now; return                     # the same field is still being dragged: same undo step\n        self._undo.append(copy.deepcopy(self.graph))\n        if len(self._undo) > self.UNDO_LIMIT: del self._undo[0]\n        self._redo.clear(); self._last_key, self._last_t = key, now\n\n    def _changed(self):\n        self.version += 1\n        if self.on_change: self.on_change()\n\n    def undo(self) -> bool:\n        if not self._undo: return False\n        self._redo.append(copy.deepcopy(self.graph)); self.graph = self._undo.pop(); self._last_key = None; self._changed(); return True\n\n    def redo(self) -> bool:\n        if not self._redo: return False\n        self._undo.append(copy.deepcopy(self.graph)); self.graph = self._redo.pop(); self._last_key = None; self._changed(); return True\n\n    # -- lookups --\n    def node(self, nid): return next((n for n in self.graph["nodes"] if n["id"] == nid), None)\n    def links_of(self, nid): return [l for l in self.graph["links"] if l["from"] == nid or l["to"] == nid]\n    def link_into(self, b, ti): return next((l for l in self.graph["links"] if l["to"] == b and l["ti"] == ti), None)\n\n    # -- editing --\n    def load(self, graph):\n        self.graph = normalize(graph); self._undo.clear(); self._redo.clear(); self._last_key = None; self.mark_saved(); self._changed()\n\n    def add_node(self, typ, x=0.0, y=0.0, p=None):\n        if typ not in FX_NODE_TYPES: return None\n        self._push()\n        n = {"id": new_id(), "type": typ, "x": round(float(x), 1), "y": round(float(y), 1), "p": node_defaults(typ)}\n        if p: n["p"].update(p)\n        self.graph["nodes"].append(n); self._changed(); return n["id"]\n\n    def remove_nodes(self, ids):\n        ids = set(ids)\n        outs = [n for n in self.graph["nodes"] if n["type"] == "fx_output"]\n        keep_out = [n for n in outs if n["id"] not in ids]\n        if outs and not keep_out: ids -= {n["id"] for n in outs}       # an effect always keeps its Output\n        ids = {i for i in ids if self.node(i)}\n        if not ids: return False\n        self._push()\n        self.graph["nodes"] = [n for n in self.graph["nodes"] if n["id"] not in ids]\n        self.graph["links"] = [l for l in self.graph["links"] if l["from"] not in ids and l["to"] not in ids]\n        self._changed(); return True\n\n    def add_link(self, a, fo, b, ti):\n        """(True, \'\') or (False, reason). An input holds one link: a new one replaces the old one."""\n        why = link_problem(self.graph, a, fo, b, ti)\n        if why: return False, why\n        if any(l["from"] == a and l["fo"] == fo and l["to"] == b and l["ti"] == ti for l in self.graph["links"]): return True, ""\n        self._push()\n        self.graph["links"] = [l for l in self.graph["links"] if not (l["to"] == b and l["ti"] == ti)]\n        self.graph["links"].append({"from": a, "fo": fo, "to": b, "ti": ti}); self._changed(); return True, ""\n\n    def remove_link(self, a, fo, b, ti):\n        n = len(self.graph["links"])\n        if not any(l["from"] == a and l["fo"] == fo and l["to"] == b and l["ti"] == ti for l in self.graph["links"]): return False\n        self._push()\n        self.graph["links"] = [l for l in self.graph["links"] if not (l["from"] == a and l["fo"] == fo and l["to"] == b and l["ti"] == ti)]\n        self._changed(); return True\n\n    def set_param(self, nid, key, value):\n        n = self.node(nid)\n        if n is None or n["p"].get(key) == value: return False\n        self._push(("p", nid, key)); n["p"][key] = value; self._changed(); return True\n\n    def set_expose(self, nid, key, on, label=None):\n        n = self.node(nid)\n        if n is None or not can_expose(n["type"], key): return False\n        ex = dict(n.get("ex") or {})\n        if on:\n            lab = (label or ex.get(key) or param_spec(n["type"], key)[1])\n            if ex.get(key) == lab: return False\n            ex[key] = str(lab)[:40]\n        elif key in ex: del ex[key]\n        else: return False\n        self._push(("ex", nid, key)); \n        if ex: n["ex"] = ex\n        else: n.pop("ex", None)\n        self._changed(); return True\n\n    def set_mute(self, ids, on=None):\n        ns = [n for n in (self.node(i) for i in ids) if n and n["type"] not in ("fx_input", "fx_output")]\n        if not ns: return False\n        on = (not all(n.get("mute") for n in ns)) if on is None else bool(on)\n        self._push()\n        for n in ns:\n            if on: n["mute"] = True\n            else: n.pop("mute", None)\n        self._changed(); return True\n\n    def move_nodes(self, pos: dict):\n        """pos: {node id: (x, y)}. One undo step per drag (the window calls this when the mouse is released)."""\n        moved = {i: p for i, p in pos.items() if self.node(i) and (round(self.node(i)["x"], 1), round(self.node(i)["y"], 1)) != (round(p[0], 1), round(p[1], 1))}\n        if not moved: return False\n        self._push()\n        for i, (x, y) in moved.items(): n = self.node(i); n["x"], n["y"] = round(float(x), 1), round(float(y), 1)\n        self._changed(); return True\n\n    # -- clipboard --\n    def copy_nodes(self, ids) -> str:\n        """The chosen nodes (not the Output) with the links between them, as text for the clipboard."""\n        ids = {i for i in ids if self.node(i) and self.node(i)["type"] != "fx_output"}\n        nodes = [copy.deepcopy(n) for n in self.graph["nodes"] if n["id"] in ids]\n        links = [dict(l) for l in self.graph["links"] if l["from"] in ids and l["to"] in ids]\n        return json.dumps({"kind": CLIP_KIND, "nodes": nodes, "links": links})\n\n    @staticmethod\n    def parse_clip(text):\n        try: d = json.loads(text)\n        except Exception: return None\n        if not isinstance(d, dict) or d.get("kind") != CLIP_KIND or not isinstance(d.get("nodes"), list) or not d["nodes"]: return None\n        return d\n\n    def paste(self, text, dx=40.0, dy=40.0):\n        """Paste what copy_nodes made (it may come from another effect). Returns the new node ids."""\n        d = self.parse_clip(text)\n        if d is None: return []\n        sub = normalize({"nodes": [n for n in d["nodes"] if isinstance(n, dict) and n.get("type") != "fx_output"], "links": d.get("links", [])})\n        if not sub["nodes"]: return []\n        self._push()\n        remap = {}\n        # normalize() may have given new ids to duplicates; match links by the ids that survived\n        for n in sub["nodes"]:\n            old = n["id"]; n = copy.deepcopy(n); n["id"] = new_id(); n["x"] = round(n["x"] + dx, 1); n["y"] = round(n["y"] + dy, 1)\n            remap[old] = n["id"]; self.graph["nodes"].append(n)\n        for l in sub["links"]:\n            if l["from"] in remap and l["to"] in remap:\n                self.graph["links"].append({"from": remap[l["from"]], "fo": l["fo"], "to": remap[l["to"]], "ti": l["ti"]})\n        self._changed(); return list(remap.values())\n\n    def duplicate(self, ids): return self.paste(self.copy_nodes(ids))\n\n    # -- tidy up --\n    def arrange(self, col_w=300.0, row_h=180.0):\n        """Left to right by how far a node is from the picture source; keeps the order up-down that nodes already had."""\n        nodes = self.graph["nodes"]\n        if not nodes: return False\n        pred = {n["id"]: [] for n in nodes}\n        for l in self.graph["links"]: pred[l["to"]].append(l["from"])\n        depth = {}\n        def d_of(i, seen=()):\n            if i in depth: return depth[i]\n            if i in seen: return 0\n            depth[i] = 1 + max((d_of(p, seen + (i,)) for p in pred[i]), default=-1); return depth[i]\n        for n in nodes: d_of(n["id"])\n        cols = {}\n        for n in sorted(nodes, key=lambda n: (n["y"], n["x"])): cols.setdefault(depth[n["id"]], []).append(n)\n        self._push()\n        for c, col in cols.items():\n            y = 0.0\n            for n in col:\n                n["x"] = round(40.0 + c * col_w, 1); n["y"] = round(40.0 + y, 1)\n                y += max(row_h * 0.6, 34 + 26 * len(node_rows(n["type"])) + 36)\n        self._changed(); return True\n\n    # -- checks --\n    def validate(self):\n        """(error message or None, [warnings]) - by compiling the graph exactly as the renderer will."""\n        try:\n            fn = compile_effect(self.graph, [])\n            return None, list(getattr(fn, "_fx_warnings", []))\n        except Exception as ex:\n            return (str(ex).splitlines()[0] if str(ex) else "error"), []\n\n    def param_specs(self): return collect_param_specs(self.graph)\n', 'minicut/workspace/fx_preview_engine.py': '"""FX editor preview engine (Patch 52) - no Qt in it.\n\nThe preview applies the effect that is being built to ONE picture and loops it for a few seconds, so animated nodes\n(Time, Wave, Noise, Wave (LFO) ...) can be seen moving. The picture comes from the project\'s own media, from a file, or\nfrom a built-in test picture. To stay light on the computer the picture is processed at a reduced size, and that size\nadapts to how fast the effect runs; a graph that does not move is rendered once and then left alone.\n"""\nimport os, time\nfrom types import SimpleNamespace\n\nimport cv2\nimport numpy as np\n\nfrom ..render.fxpack.custom import FX_NODE_TYPES, compile_effect, collect_param_specs\n\nLOOP_SECONDS = 3.0\nBASE_WIDTH = 960               # the picture is kept at most this wide; the work size is a fraction of it\nSAMPLE_NAMES = ["Color bars", "Landscape", "Shapes", "Gray ramp"]\n_TIME_NODES = ("fx_time", "fx_lfo", "fx_wave_warp", "fx_noise_tex")\n\n\n# ── test pictures ─────────────────────────────────────────────────────────────\n\ndef sample_picture(name: str, w: int = 960, h: int = 540) -> np.ndarray:\n    """A BGRA test picture with colour, detail and edges (so most effects show something)."""\n    img = np.zeros((h, w, 4), np.uint8); img[..., 3] = 255\n    if name == "Color bars":\n        cols = [(255, 255, 255), (0, 255, 255), (255, 255, 0), (0, 255, 0), (255, 0, 255), (0, 0, 255), (255, 0, 0), (0, 0, 0)]   # BGR\n        bw = max(1, w // len(cols))\n        for i, c in enumerate(cols): img[: int(h * 0.75), i * bw: (i + 1) * bw if i < len(cols) - 1 else w, :3] = c\n        ramp = np.linspace(0, 255, w, dtype=np.uint8)[None, :]\n        img[int(h * 0.75):, :, 0] = ramp; img[int(h * 0.75):, :, 1] = ramp; img[int(h * 0.75):, :, 2] = ramp\n    elif name == "Landscape":\n        t = np.linspace(0.0, 1.0, h, dtype=np.float32)[:, None]\n        sky_top = np.array([180, 110, 40], np.float32); sky_low = np.array([90, 150, 255], np.float32)      # BGR\n        img[..., :3] = np.clip(sky_top[None, None, :] * (1 - t[..., None]) + sky_low[None, None, :] * t[..., None], 0, 255).astype(np.uint8)\n        cv2.circle(img, (int(w * 0.72), int(h * 0.42)), int(h * 0.12), (170, 240, 255, 255), -1, cv2.LINE_AA)\n        x = np.arange(w, dtype=np.float32)\n        for k, (base, amp, col) in enumerate(((0.62, 0.07, (96, 70, 60)), (0.72, 0.06, (60, 45, 35)), (0.84, 0.05, (30, 22, 18)))):\n            ridge = (base + amp * np.sin(x / w * (5 + 3 * k) + k * 1.7) + 0.02 * np.sin(x / w * (23 + 7 * k))) * h\n            yy = np.arange(h, dtype=np.float32)[:, None]\n            img[yy >= ridge[None, :], :3] = col\n    elif name == "Shapes":\n        t = np.linspace(0.0, 1.0, w, dtype=np.float32)[None, :]\n        img[..., 0] = (40 + 60 * t).astype(np.uint8); img[..., 1] = 30; img[..., 2] = (70 + 30 * (1 - t)).astype(np.uint8)\n        cv2.circle(img, (int(w * 0.25), int(h * 0.5)), int(h * 0.28), (60, 200, 255, 255), -1, cv2.LINE_AA)\n        cv2.rectangle(img, (int(w * 0.45), int(h * 0.2)), (int(w * 0.7), int(h * 0.8)), (255, 140, 40, 255), -1)\n        cv2.circle(img, (int(w * 0.82), int(h * 0.5)), int(h * 0.2), (120, 255, 120, 255), 6, cv2.LINE_AA)\n        cv2.putText(img, "MINICUT", (int(w * 0.08), int(h * 0.92)), cv2.FONT_HERSHEY_SIMPLEX, h / 260.0, (255, 255, 255, 255), max(2, h // 140), cv2.LINE_AA)\n    else:                                                      # "Gray ramp"\n        ramp = np.linspace(0, 255, w, dtype=np.uint8)[None, :]\n        for c in range(3): img[..., c] = ramp\n        img[: h // 2, : w // 6, :3] = 0; img[h // 2:, -w // 6:, :3] = 255\n    return img\n\n\n# ── loading the picture ───────────────────────────────────────────────────────\n\ndef _fit(img: np.ndarray, max_w: int) -> np.ndarray:\n    if img is None: return None\n    h, w = img.shape[:2]\n    if w <= max_w: return np.ascontiguousarray(img)\n    return cv2.resize(img, (max_w, max(1, int(round(h * max_w / w)))), interpolation=cv2.INTER_AREA)\n\n\ndef _to_bgra(img):\n    if img is None: return None\n    if img.dtype != np.uint8: img = np.clip(img / 256.0 if img.dtype == np.uint16 else img, 0, 255).astype(np.uint8)\n    if img.ndim == 2: return cv2.cvtColor(img, cv2.COLOR_GRAY2BGRA)\n    if img.shape[2] == 3: return cv2.cvtColor(img, cv2.COLOR_BGR2BGRA)\n    return img\n\n\ndef _read_image_file(path):\n    try: img = cv2.imdecode(np.fromfile(path, np.uint8), cv2.IMREAD_UNCHANGED)       # works with Thai / unicode paths\n    except Exception: img = None\n    if img is None:\n        try:\n            from PIL import Image\n            im = Image.open(path); im.load(); img = cv2.cvtColor(np.array(im.convert("RGBA")), cv2.COLOR_RGBA2BGRA)\n        except Exception: img = None\n    return _to_bgra(img)\n\n\ndef _read_video_frame(path, t):\n    try:\n        try:\n            from ..render.media import safe_path as _sp\n            path = _sp(path)\n        except Exception: pass\n        cap = cv2.VideoCapture(path); cap.set(cv2.CAP_PROP_POS_MSEC, max(0.0, t) * 1000.0)\n        ok, img = cap.read()\n        if not ok: cap.set(cv2.CAP_PROP_POS_FRAMES, 0); ok, img = cap.read()\n        cap.release()\n        return _to_bgra(img) if ok else None\n    except Exception: return None\n\n\ndef load_picture(spec: dict, max_w: int = BASE_WIDTH):\n    """spec: {"type": "sample", "name": ...} | {"type": "file", "path": ...} | {"type": "clip", "path", "kind", "t"}.\n    Returns a BGRA picture (at most max_w wide) or None when it cannot be read."""\n    if not isinstance(spec, dict): return None\n    typ = spec.get("type")\n    try:\n        if typ == "sample": return sample_picture(spec.get("name", SAMPLE_NAMES[0]), min(max_w, BASE_WIDTH), int(min(max_w, BASE_WIDTH) * 9 / 16))\n        path = spec.get("path")\n        if not path or not os.path.exists(path): return None\n        if typ == "file": return _fit(_read_image_file(path), max_w)\n        if typ == "clip":\n            kind = spec.get("kind")\n            img = _read_video_frame(path, float(spec.get("t", 0.0))) if kind == "video" else _read_image_file(path)\n            return _fit(img, max_w)\n    except Exception:\n        return None\n    return None\n\n\n# ── is the effect moving? ─────────────────────────────────────────────────────\n\ndef graph_is_animated(graph: dict) -> bool:\n    """True when something in the graph changes over time (so the preview has to keep redrawing)."""\n    graph = graph or {}\n    driven = set()\n    for lk in graph.get("links", []):\n        try:\n            if int(lk.get("ti", 0)) >= len(FX_NODE_TYPES.get(next((n["type"] for n in graph.get("nodes", []) if n.get("id") == lk.get("to")), ""), {}).get("ins", [])):\n                driven.add(lk.get("to"))\n        except Exception: pass\n    for n in graph.get("nodes", []):\n        if not isinstance(n, dict) or n.get("mute") or n.get("type") not in _TIME_NODES: continue\n        p = n.get("p") or {}\n        def num(k, d):\n            try: return float(p.get(k, d))\n            except Exception: return d\n        typ = n["type"]\n        if n.get("id") in driven or typ == "fx_time": return True        # a wired parameter may follow time: keep drawing\n        if typ == "fx_noise_tex" and num("speed", 0.5) > 1e-9: return True\n        if typ == "fx_wave_warp" and abs(num("amp", 20.0)) > 1e-9 and abs(num("speed", 1.0)) > 1e-9: return True\n        if typ == "fx_lfo" and abs(num("speed", 0.5)) > 1e-9: return True\n    return False\n\n\n# ── the engine ────────────────────────────────────────────────────────────────\n\nclass FxPreview:\n    TARGET_MS = 45.0            # about 20 pictures a second\n    TOO_SLOW_MS = 80.0\n\n    def __init__(self, ref_width: float = 1920.0):\n        self.base = None            # the picture, at most BASE_WIDTH wide\n        self.work = None            # the picture at the current work size\n        self.scale = 1.0\n        self.ref_width = float(ref_width)     # width of the project\'s picture: sizes in pixels are scaled to this\n        self.fn = None; self.error = None; self.warnings = []\n        self.values = {}            # slider values: exposed parameters and Parameter nodes\n        self.animated = False\n        self.last_ms = 0.0; self.last = None\n        self._fast_run = 0\n\n    # -- inputs --\n    def set_source(self, img):\n        self.base = img if img is None else _fit(_to_bgra(img), BASE_WIDTH); self.scale = 1.0; self._make_work(); self.last = None\n\n    def set_graph(self, graph: dict) -> bool:\n        """Compile the graph. On an error the previous effect keeps running and `error` says what is wrong."""\n        try:\n            fn = compile_effect(graph, [])\n        except Exception as ex:\n            self.error = str(ex).splitlines()[0] if str(ex) else "error"; return False\n        self.fn = fn; self.error = None; self.warnings = list(getattr(fn, "_fx_warnings", [])); self.animated = graph_is_animated(graph)\n        self.last = None\n        # sliders: a value the person has moved stays; new sliders start at the node\'s own value\n        specs = collect_param_specs(graph)\n        self.values = {s[0]: self.values.get(s[0], s[3]) for s in specs}\n        return True\n\n    def set_value(self, key, v): self.values[key] = v; self.last = None\n\n    # -- work size --\n    def _make_work(self):\n        if self.base is None: self.work = None; return\n        h, w = self.base.shape[:2]; s = max(0.2, min(1.0, self.scale))\n        self.work = self.base if s >= 0.999 else cv2.resize(self.base, (max(8, int(w * s)), max(8, int(h * s))), interpolation=cv2.INTER_AREA)\n\n    def _adapt(self, ms):\n        """Slow effect -> smaller picture; plenty of time to spare -> bigger again (slowly, so it does not flicker)."""\n        if ms > self.TOO_SLOW_MS and self.scale > 0.21:\n            self.scale = max(0.2, self.scale * 0.8); self._fast_run = 0; self._make_work()\n        elif ms < self.TARGET_MS * 0.5 and self.scale < 1.0:\n            self._fast_run += 1\n            if self._fast_run >= 15: self.scale = min(1.0, self.scale * 1.15); self._fast_run = 0; self._make_work()\n        else: self._fast_run = 0\n\n    # -- output --\n    def render(self, t: float):\n        """The effect applied to the picture at time t (looped over LOOP_SECONDS). None when there is no picture or no\n        working effect yet. A still graph is rendered once and then the same picture is returned."""\n        if self.work is None or self.fn is None: return None\n        if not self.animated and self.last is not None: return self.last\n        lt = float(t) % LOOP_SECONDS\n        ctx = SimpleNamespace(k=max(1e-3, self.work.shape[1] / self.ref_width), lt=lt, fast=False,\n                              clip={"start": 0.0, "dur": LOOP_SECONDS}, holder={}, progress_keyframed=False)\n        t0 = time.perf_counter()\n        try: out = self.fn(self.work, dict(self.values), ctx)\n        except Exception as ex:\n            self.error = "while running: " + (str(ex).splitlines()[0] if str(ex) else "error"); return self.last\n        self.last_ms = (time.perf_counter() - t0) * 1000.0\n        self.last = out\n        if self.animated: self._adapt(self.last_ms)\n        return out\n'}
PAYLOAD = {'minicut/render/fxpack/custom.py': '', 'minicut/workspace/fx_node_editor.py': ''}
HERE = os.path.dirname(os.path.abspath(__file__))
def _find_root():
    env = os.environ.get("MINICUT_ROOT")
    cands = ([env] if env else []) + [HERE, os.path.join(HERE, "minicut"), os.path.dirname(HERE), os.path.join(os.path.dirname(HERE), "minicut")]
    for c in cands:
        if c and os.path.isfile(os.path.join(c, "minicut", "app.py")): return c
    return HERE
ROOT = _find_root()
_LAUNCHER_DIR = os.path.dirname(ROOT)                      # the Launcher keeps its backups next to its own file
BACKUP_ROOT = os.path.join(_LAUNCHER_DIR, "_patch_backup") if os.path.isfile(os.path.join(_LAUNCHER_DIR, "MiniCut_Launcher.pyw")) else os.path.join(ROOT, "_patch_backup")
BACKUP_ROOTS = [BACKUP_ROOT] + ([os.path.join(ROOT, "_patch_backup")] if os.path.join(ROOT, "_patch_backup") != BACKUP_ROOT else [])


def norm_hash(b): return hashlib.sha256(b.replace(b"\r\n", b"\n")).hexdigest()
def path_of(rel): return os.path.join(ROOT, *rel.split("/"))
def read(rel):
    try:
        with open(path_of(rel), "rb") as f: return f.read()
    except OSError: return None
def new_bytes(rel):
    return zlib.decompress(base64.b64decode(PAYLOAD[rel]))
def latest_backup():
    found = []
    for root in BACKUP_ROOTS:
        if not os.path.isdir(root): continue
        for d in os.listdir(root):
            mf = os.path.join(root, d, "MANIFEST.json")
            if os.path.isfile(mf):
                try:
                    with open(mf, encoding="utf-8") as f:
                        if json.load(f).get("patch") == PATCH_NAME: found.append((d, os.path.join(root, d)))
                except Exception: pass
    return sorted(found)[-1][1] if found else None


def revert():
    bdir = latest_backup()
    if not bdir: print("No backup of this update was found."); return 1
    with open(os.path.join(bdir, "MANIFEST.json"), encoding="utf-8") as f: m = json.load(f)
    for rel in m.get("replaced", []): shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
    for rel in m.get("created", []):
        try: os.remove(path_of(rel))
        except OSError: pass
    os.replace(os.path.join(bdir, "MANIFEST.json"), os.path.join(bdir, "MANIFEST.undone.json"))
    print("Reverted from backup:", bdir); return 0


def main():
    if not os.path.isfile(os.path.join(ROOT, "minicut", "app.py")):
        print("ERROR: the MiniCut folder was not found. Put this file in MiniCut/Patch/ (or next to the minicut folder)."); return 2
    if "--revert" in sys.argv: return revert()
    todo_replace, todo_new, already = [], [], 0
    for rel, h in REPLACE.items():
        cur = read(rel)
        if cur is None: print("STOPPED: missing file", rel, "- no files were changed."); return 3
        c = norm_hash(cur); bases = h["base"] if isinstance(h["base"], (list, tuple)) else [h["base"]]
        if c == h["new"]: already += 1
        elif c in bases: todo_replace.append(rel)
        else:
            print("STOPPED:", rel, "is not the version this update expects (it was changed by hand or by another update).")
            print("No files were changed. This protects your own edits."); return 3
    for rel, text in NEW_FILES.items():
        cur = read(rel)
        if cur is None: todo_new.append(rel)
        elif norm_hash(cur) == norm_hash(text.encode("utf-8")): already += 1
        else: print("STOPPED:", rel, "already exists with other content. No files were changed."); return 3
    if not todo_replace and not todo_new: print("This update is already installed."); return 0
    if "--check" in sys.argv:
        print("Check passed. Would change:", ", ".join(todo_replace + todo_new)); return 0
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S"); bdir = os.path.join(BACKUP_ROOT, stamp); k = 1
    while os.path.exists(bdir): k += 1; bdir = os.path.join(BACKUP_ROOT, "%s_%d" % (stamp, k))      # two installs in one second
    os.makedirs(bdir, exist_ok=False)
    for rel in todo_replace:
        dst = os.path.join(bdir, *rel.split("/")); os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy2(path_of(rel), dst)
    with open(os.path.join(bdir, "MANIFEST.json"), "w", encoding="utf-8") as f:
        json.dump({"patch": PATCH_NAME, "created": todo_new, "replaced": todo_replace}, f, indent=2)
    try:
        for rel in todo_replace:
            cur = read(rel); data = new_bytes(rel).replace(b"\r\n", b"\n")
            if b"\r\n" in cur: data = data.replace(b"\n", b"\r\n")            # keep the file's own line endings
            with open(path_of(rel), "wb") as f: f.write(data)
            if norm_hash(read(rel)) != REPLACE[rel]["new"]: raise RuntimeError("hash mismatch after writing " + rel)
        for rel in todo_new:
            os.makedirs(os.path.dirname(path_of(rel)), exist_ok=True)
            with open(path_of(rel), "wb") as f: f.write(NEW_FILES[rel].encode("utf-8"))
        for rel in todo_replace + todo_new:
            if rel.endswith(".py"): py_compile.compile(path_of(rel), doraise=True)
    except Exception as ex:
        for rel in todo_replace: shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
        for rel in todo_new:
            try: os.remove(path_of(rel))
            except OSError: pass
        print("ERROR: the update failed and every file was put back:", repr(ex)); return 1
    print("Installed Patch 52. Changed:", ", ".join(todo_replace + todo_new)); print("Backup:", bdir); return 0


if __name__ == "__main__":
    try: code = main()
    except Exception as ex: print("Unexpected error:", repr(ex)); code = 1
    sys.exit(code)
